    version_id, parent_id, comments,
    added_by, added_timestamp, moderated_by, moderated_timestamp
)
SELECT
    t.shape__len, t.trackname, t.lastcheck,
    'Various/ Offers?'  AS custodian,
    1704067200                  AS lastcut,
    'Medium' AS importance,
    'Reasonably good.'  AS currentcon,
    t.hikinggrad, t.maintenanc, t.marking, t.docregion,
    t.altitudech, t.warnings, t.conservati, t.tracktype,
    t.currentc_1, t.disttops, t.lengthinbu, t.datasource,
    t.isroutegis, t.complete, t.globalid, t.slopedist, t.infonote,
    '?'                  AS nextcut,
    t.xyz_distan, t.zvalues_ca, t.docregionb, t.custodiang,
    t.layer_name,
    t.geom                         AS geom,  -- unchanged geometry (copied from prod)
    t.original, t.rollback, t.multiple_status,
    t.status_overlay_links, t.existing_track_info_field_links,
    nextval('permolat_track_versions_version_id_seq') AS version_id,
    t.id                           AS parent_id,
    'Maintenance schedule update — PDF: Yeats Ridge Hut up onto Toaroha Range'                    AS comments,
    1                              AS added_by,
    NOW()                          AS added_timestamp,
    NULL                           AS moderated_by,
    NOW()                          AS moderated_timestamp
FROM permolat_tracks_prod t WHERE t.id = 59;

COMMIT;